<script setup>
import { ref, computed } from 'vue'
import { useRouter } from 'vue-router'
import { useEvents } from '@/composables/useEvents'
import AppModal from '@/components/ui/AppModal.vue'
import OrganizerEventCard from '@/components/event/OrganizerEventCard.vue'
import EventCreateForm from '@/components/event/EventCreateForm.vue'
const router = useRouter()
const { activeEvents, completedEvents, completeEvent, deleteEvent } = useEvents()
const currentTab = ref('active'), isModalOpen = ref(false), selectedEvent = ref(null), modalAction = ref('complete'), successMessage = ref('')
const modalTitle = computed(() => modalAction.value === 'complete' ? 'Complete Event?' : 'Delete Event Permanently?')
const modalMessage = computed(() => modalAction.value === 'complete' ? `Are you sure you want to mark "${selectedEvent.value?.title}" as completed? Once completed, the event will automatically be removed from public listings.` : `Are you sure you want to permanently delete "${selectedEvent.value?.title}"? This action cannot be undone and will permanently remove this event and all its registrations.`)
function handleCompleteEvent(event) { selectedEvent.value=event;modalAction.value='complete';isModalOpen.value=true }
function handleDeleteEvent(event) { selectedEvent.value=event;modalAction.value='delete';isModalOpen.value=true }
function handleConfirmModal() { if (selectedEvent.value) { if(modalAction.value==='complete') completeEvent(selectedEvent.value.id);else deleteEvent(selectedEvent.value.id) };isModalOpen.value=false;selectedEvent.value=null }
function onCreated() { currentTab.value='active';successMessage.value='Event published successfully and is now live!' }
</script><template><div class="event-management-page"><header class="page-header"><h2>Event Management Control</h2><p>Manage event lifecycle, publish new events, and archive completed records.</p></header><div class="tab-container"><button :class="['tab-btn',{active:currentTab==='active'}]" @click="currentTab='active';successMessage=''">⚡ Active Events ({{ activeEvents.length }})</button><button :class="['tab-btn',{active:currentTab==='create'}]" @click="currentTab='create';successMessage=''">＋ Create Event</button><button :class="['tab-btn',{active:currentTab==='completed'}]" @click="currentTab='completed';successMessage=''">✅ Completed Events ({{ completedEvents.length }})</button></div><p v-if="successMessage" class="alert-success">{{ successMessage }}</p><section v-if="currentTab==='active'" class="event-grid"><OrganizerEventCard v-for="item in activeEvents" :key="item.id" :event="item" @view-detail="router.push(`/browse/events/${$event}`)" @complete="handleCompleteEvent" @delete="handleDeleteEvent"/><div v-if="!activeEvents.length" class="empty-state"><h3>No Active Events Yet</h3><p>All active events have ended or none have been created yet. Please create a new event!</p><button class="btn-primary" @click="currentTab='create'">Create Your First Event</button></div></section><EventCreateForm v-else-if="currentTab==='create'" @success="onCreated" @cancel="currentTab='active'"/><section v-else class="event-grid"><OrganizerEventCard v-for="item in completedEvents" :key="item.id" :event="item" is-completed @delete="handleDeleteEvent"/><div v-if="!completedEvents.length" class="empty-state"><h3>No Completed Events Yet</h3><p>Completed events will be archived here after they are marked as finished.</p></div></section><AppModal :is-open="isModalOpen" :title="modalTitle" :message="modalMessage" :confirm-text="modalAction==='complete'?'Yes, Complete':'Yes, Delete Permanently'" @close="isModalOpen=false" @confirm="handleConfirmModal"/></div></template>
<style scoped>.event-management-page{max-width:1250px;margin:auto}.page-header h2{font-size:1.9rem;margin:0 0 10px}.page-header p{color:var(--text-muted);font-size:.9rem;margin:0 0 26px}.tab-container{display:flex;gap:12px;flex-wrap:wrap;border-bottom:1px solid var(--border-color);margin-bottom:24px;padding-bottom:12px}.tab-btn{border:0;background:transparent;color:var(--text-muted);padding:12px 18px;border-radius:8px;cursor:pointer;font-weight:650}.tab-btn.active{background:var(--primary);color:white;box-shadow:0 5px 12px rgba(102,68,255,.2)}.event-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:20px}.empty-state{grid-column:1/-1;text-align:center;background:#fff;border:1px solid var(--border-color);border-radius:12px;padding:46px 20px}.empty-state p{color:var(--text-muted);margin:12px auto 22px}.btn-primary{border:0;background:var(--primary);color:#fff;padding:12px 18px;border-radius:8px;cursor:pointer}.alert-success{background:#dcfce7;color:#16803d;border-radius:8px;padding:14px 16px;margin-bottom:20px}</style>
